const mine = $('WhatsApp Trigger').first().json.messages[0].id;
const rows = $input.all().map(i => i.json).filter(r => r && r.wamid);
rows.sort((a, b) => new Date(a.created_at) - new Date(b.created_at) || String(a.wamid).localeCompare(String(b.wamid)));
if (!rows.length) return [];                                  // already handled by a newer run
if (rows[rows.length - 1].wamid !== mine) return [];          // a newer message arrived: let that run answer
return [{ json: {
  combined_text: rows.map(r => String(r.body).trim()).filter(Boolean).join(' / '),
  message_count: rows.length,
  last_created_at: rows[rows.length - 1].created_at
} }];

const trig = $('WhatsApp Trigger').first().json;
const msg = (trig.messages && trig.messages[0]) || {};
const wa_id = (trig.contacts && trig.contacts[0] && trig.contacts[0].wa_id) || msg.from;
const text = $('Combined Message').first().json.combined_text || '';
if (!text) throw new Error('NO_TEXT: not a customer text message');
const lead = $('Get Lead').first().json;
const snapshot = lead && lead.id ? JSON.stringify(lead) : 'NONE';
const decisions = $('Get Latest Decisions').all().map(i => i.json)
  .filter(r => r && r.approval_request_id && r.approval_status && r.approval_status !== 'PENDING');
decisions.sort((a, b) => new Date(b.resolved_at) - new Date(a.resolved_at));
const dec = decisions[0];
const team = dec ? '\nTEAM_DECISION: ' + JSON.stringify({
  topic: dec.requested_action || dec.issue_description || null,
  property: dec.property_name || null,
  decision: dec.approval_status,
  team_note: dec.approval_instruction || null,
  already_told_customer: dec.reply_sent_to_customer || null
}) : '';
const now = new Date().toLocaleString('en-IN', { timeZone: 'Asia/Kolkata', dateStyle: 'full', timeStyle: 'short' });
const agent_input = `WHATSAPP_ID: ${wa_id}\nCURRENT_TIME_IST: ${now}\nSAVED_LEAD_RECORD: ${snapshot}${team}\nCUSTOMER_MESSAGE: ${text}`;
return [{ json: { agent_input, wa_id, contacts: trig.contacts, messages: trig.messages } }];
